 * @param createdAt     封存登记时间（Asia/Shanghai）
 */
public record SealedContent(
        Long id,
        String evidenceKey,
        int versionNo,
        String contentSha256,
        LocalDateTime createdAt) {
}

package com.example.starter.evidence;

import java.time.LocalDateTime;

/**
 * 数字摘要见证实体，对应 digest_witness 表。记录只追加：
 * 一名保管人对某证物某一封存版本的确认；版本失效后该见证不会转移到新版本。
 *
 * @param id          主键
 * @param evidenceKey 关联证物业务键
 * @param versionNo   被见证的封存版本号
 * @param witnessId   见证保管人标识，须为该证物历任或现任保管人，同版本两人不得重复
 * @param createdAt   见证提交时间（Asia/Shanghai）
 */
public record DigestWitness(
        Long id,
        String evidenceKey,
        int versionNo,
        String witnessId,
        LocalDateTime createdAt) {
}

package com.example.starter.evidence;

import java.time.LocalDateTime;

/**
 * 导出包实体，对应 export_package 表。仅当包内全部证物摘要重算匹配、
 * 两名不同见证齐备时才生成；生成后不可变，后续内容变化不改写已导出包。
 *
 * @param id          主键
 * @param packageKey  导出包业务标识，生成后不可变；同一 requestId 重放返回该标识
 * @param requestId   导出请求幂等键，全局唯一；同键同证物集合重放首次包，换集合返回 409
 * @param createdAt   导出包生成时间（Asia/Shanghai）
 */
public record ExportPackage(
        Long id,
        String packageKey,
        String requestId,
        LocalDateTime createdAt) {
}

package com.example.starter.evidence;

/**
 * 导出包清单条目实体，对应 export_package_item 表。建包时每件证物摘要的快照，
 * 只追加、不可变；后续证物内容变化不影响已导出清单。
 *
 * @param id            主键
 * @param packageId     关联导出包主键
 * @param evidenceKey   包内证物业务键
 * @param contentSha256 建包时该证物封存版本登记的 SHA-256 摘要快照
 */
public record ExportPackageItem(
        Long id,
        Long packageId,
        String evidenceKey,
        String contentSha256) {
}

