 */
public record ExportItemView(
        String evidenceKey,
        int versionNo,
        String contentSha256) {
}

package com.example.starter.evidence.dto;

import java.time.LocalDateTime;
import java.util.List;

/**
 * 导出包视图：包标识、裁决版本与逐件证物摘要清单。重放同一 requestId 返回与首次完全一致的内容。
 *
